let ac=null;
function ensureAudio(){ if(save.mute) return; try{ if(!ac) ac=new (window.AudioContext||window.webkitAudioContext)(); if(ac.state==='suspended') ac.resume(); }catch(e){ac=null;} }
function tone(f,dur,delay=0,type='sine',vol=0.07){ if(save.mute||!ac) return; const t=ac.currentTime+delay; const o=ac.createOscillator(), g=ac.createGain(); o.type=type; o.frequency.value=f; g.gain.setValueAtTime(0,t); g.gain.linearRampToValueAtTime(vol,t+0.008); g.gain.setValueAtTime(vol,t+dur-0.01); g.gain.linearRampToValueAtTime(0,t+dur); o.connect(g).connect(ac.destination); o.start(t); o.stop(t+dur+0.02); }
function morse(code,delay=0){ let t=delay; const u=0.07; for(const ch of code){ if(ch==='.'){tone(700,u,t);t+=u*2;} else if(ch==='-'){tone(700,u*3,t);t+=u*4;} else t+=u*3; } }
let noiseBuf=null;
function knockSnd(delay=0,vol=1){ if(save.mute||!ac) return; if(!noiseBuf){ noiseBuf=ac.createBuffer(1,ac.sampleRate*0.08,ac.sampleRate); const d=noiseBuf.getChannelData(0); for(let i=0;i<d.length;i++) d[i]=(Math.random()*2-1)*Math.pow(1-i/d.length,3); }
  const t=ac.currentTime+delay; const s=ac.createBufferSource(); s.buffer=noiseBuf; const f=ac.createBiquadFilter(); f.type='bandpass'; f.frequency.value=220; f.Q.value=1.4; const g=ac.createGain(); g.gain.value=0.9*vol; s.connect(f).connect(g).connect(ac.destination); s.start(t);
  const o=ac.createOscillator(), og=ac.createGain(); o.frequency.setValueAtTime(140,t); o.frequency.exponentialRampToValueAtTime(60,t+0.09); og.gain.setValueAtTime(0.25*vol,t); og.gain.exponentialRampToValueAtTime(0.001,t+0.12); o.connect(og).connect(ac.destination); o.start(t); o.stop(t+0.14); }
