  const dim=ROOM.dim?1:0;
  const base= (dim?0.22:0.5)*(1-knock*0.9);
  R3.amb.intensity=(dim?0.12:0.3)*(1-knock*0.92); R3.hemi.intensity=(dim?0.1:0.35)*(1-knock*0.92);
  const ang=knock>0.3?0.3:(dim?0.42:0.78); R3.spot.angle=ang; R3.spot.intensity=1.5+dim*0.5+knock*0.4;
  R3.spot.position.set(p.x,640,p.y+160); R3.spot.target.position.set(p.x,0,p.y); R3.spot.target.updateMatrixWorld();
  R3.lvl={base, spotR: Math.tan(ang)*640*1.15+60};
  // camera gentle follow + shake
