  const cam=R3.camera; cam.position.copy(tgt).addScaledVector(cb.dir,cb.d); if(G.shake>0){ cam.position.x+=(Math.random()-.5)*8; cam.position.y+=(Math.random()-.5)*8; } cam.lookAt(tgt);
