  for(const o of room.pads){ const glow=!p.item && !o.pd.bin && want.includes(o.pd.i); const binGlow=o.pd.bin && p.item; o.mesh.material.emissive.set(glow?COLORS[o.pd.i]:(binGlow?'#edece8':'#000000')); o.mesh.material.emissiveIntensity=glow?0.45+0.2*Math.sin(T*5):(binGlow?0.25:0); if(o.roll) o.roll.position.y=19+(glow?Math.abs(Math.sin(T*4+o.pd.i))*4:0); }
  // portal
