  if(need && need!=='portal' && sAt && sAt.id===need && p.item.prog>0){ const s=sAt; const v=proj(s.x+s.w/2,0,s.y+s.h-18); const bw=(s.w-60)*ppu; ctx.fillStyle='rgba(16,16,18,0.7)'; rr(v.x-bw/2-3,v.y-7,bw+6,14,7); ctx.fill(); ctx.fillStyle=A; rr(v.x-bw/2,v.y-4,bw*p.item.prog,8,4); ctx.fill(); }
  // head anchor
  const a=animPose(p,c,T); const ph=(c.id==='carka'?72:100)*S3; const head=proj(p.x,ph*Math.cos(TILT)+a.bob,p.y+4-ph*Math.sin(TILT));
  if(p.ghost>0){ const v=proj(p.x,0,p.y); ctx.strokeStyle=A; ctx.setLineDash([4,6]); ctx.lineWidth=2; ctx.beginPath(); ctx.ellipse(v.x,v.y,46*ppu,30*ppu,0,0,Math.PI*2); ctx.stroke(); ctx.setLineDash([]); }
  if(p.stun>0){ ctx.font='800 18px "Bricolage Grotesque", sans-serif'; ctx.fillStyle='#edece8'; ctx.textAlign='center'; ctx.fillText('z z z',head.x+Math.sin(T*3)*6,head.y-8); }
  // carried item
  if(p.item){ const it=p.item, ix=head.x, iy=head.y-24; const done=it.si, total=it.steps.length-1; const packed=it.steps[it.si]==='portal'; const sc=Math.max(0.7,ppu*1.1);
    ctx.save(); ctx.translate(ix,iy); ctx.scale(sc,sc);
    if(packed){ ctx.fillStyle='#c9a45c'; rr(-20,-16,40,32,5); ctx.fill(); ctx.fillStyle=COLORS[it.ci]; ctx.fillRect(-20,-4,40,8); ctx.strokeStyle='rgba(16,16,18,0.5)'; ctx.lineWidth=1.5; rr(-20,-16,40,32,5); ctx.stroke(); }
    else { ctx.fillStyle=COLORS[it.ci]; ctx.beginPath(); ctx.ellipse(0,0,15,18,0,0,Math.PI*2); ctx.fill(); ctx.fillStyle='rgba(16,16,18,0.35)'; ctx.beginPath(); ctx.ellipse(0,0,5,6,0,0,Math.PI*2); ctx.fill(); }
    const gap=11, sx=-(total-1)*gap/2; for(let i=0;i<total;i++){ ctx.fillStyle=i<done?COLORS[it.ci]:'rgba(237,236,232,0.3)'; ctx.beginPath(); ctx.arc(sx+i*gap,26,3.5,0,Math.PI*2); ctx.fill(); }
    ctx.restore(); }
  // bubble
  if(p.bubble>0){ ctx.save(); ctx.globalAlpha=Math.min(1,p.bubble*3); ctx.font='800 16px "Bricolage Grotesque", sans-serif'; const tw=ctx.measureText(c.line).width+24; const bx=Math.max(8,Math.min(Wc-8-tw,head.x-tw/2)); const by=head.y-(p.item?96:56); ctx.fillStyle='#edece8'; rr(bx,by,tw,36,12); ctx.fill(); ctx.beginPath(); ctx.moveTo(head.x-7,by+36); ctx.lineTo(head.x,by+46); ctx.lineTo(head.x+7,by+36); ctx.fill(); ctx.fillStyle='#101012'; ctx.textAlign='left'; ctx.fillText(c.line,bx+12,by+24); ctx.restore(); }
  // floats
  for(const f of G.floats){ const v=proj(f.x,70,f.y); ctx.globalAlpha=1-f.t/1.2; ctx.font='800 24px "Bricolage Grotesque", sans-serif'; ctx.textAlign='center'; ctx.fillStyle=f.color; ctx.fillText(f.text,v.x,v.y-f.t*30); } ctx.globalAlpha=1;
  // freeze
  if(G.freeze>0){ ctx.save(); ctx.globalAlpha=Math.min(0.5,G.freeze)*0.7; ctx.strokeStyle=A; ctx.lineWidth=6; rr(4,4,Wc-8,Hc-8,18); ctx.stroke(); ctx.restore(); ctx.font='700 13px "Space Mono", monospace'; ctx.fillStyle=A; ctx.textAlign='center'; ctx.fillText('VŠE ZMRAZENO DLE PŘEDPISU',Wc/2,Hc-16); }
  // room name
  ctx.font='700 12px "Space Mono", monospace'; ctx.fillStyle='rgba(150,150,150,0.85)'; ctx.textAlign='left'; ctx.fillText(ROOM.name.toUpperCase(),12,Hc-12);
  if(G.adv) advOverlay((x,h,z)=>proj(x,h,z),1,true);
