function runDlg(steps){ if(A_.dlg){ A_.dlg.q.push(...steps); return; } A_.dlg={q:steps.slice()}; joy=null; G.p.goto=null; dlgNext(); }
function dlgNext(){
  const d=A_.dlg; if(!d) return;
  const box=$('dlg'), ch=$('dlgChoices');
  while(d.q.length && typeof d.q[0]==='function'){ const f=d.q.shift(); const r=f(); if(Array.isArray(r)) d.q.unshift(...r); if(A_.dlg!==d) return; }
  if(!d.q.length){ A_.dlg=null; box.classList.remove('on'); advHUD(true); advRefresh(); storyPersist(); return; }
  const s=d.q.shift();
  ch.innerHTML='';
  if(s.choices){ d.waitChoice=true; const sp=speaker(s.who||'bzucak'); $('dlgPic').src=sp.img; $('dlgPic').style.display=''; $('dlgName').textContent=sp.name; $('dlgName').style.color=sp.color; $('dlgText').textContent=s.ask||'';
    s.choices.filter(c=>!c.if||c.if()).forEach(c=>{ const b=document.createElement('button'); b.className='choice'; b.textContent=c.label; b.onclick=(e)=>{ e.stopPropagation(); d.waitChoice=false; const r=c.then?c.then():[]; d.q.unshift(...(r||[])); sfx.step(); dlgNext(); }; ch.appendChild(b); });
    box.classList.add('on'); setTimeout(()=>{ const f=ch.querySelector('button'); if(f) f.focus({preventScroll:true}); },20); return; }
  d.waitChoice=false;
  const [who,text]=s; const sp=speaker(who);
  if(sp.img){ $('dlgPic').src=sp.img; $('dlgPic').style.display=''; } else $('dlgPic').style.display='none';
  $('dlgName').textContent=sp.name; $('dlgName').style.color=sp.color; $('dlgText').textContent=text;
  box.classList.toggle('note',who==='note'); box.classList.add('on'); tone(who==='bzucak'?760:480+Math.random()*240,0.045);
}
