function SCRIPT_CHASE(){ return [ ['pipa','Nóó! Ta krabice už jede k portálu!'], ['bzucak','Když projde portálem, je v druhém světě!'], ['bzucak','Tu to dej! Chytím ji!'], ()=>{ startChase(); return []; } ]; }

/* ---------- chase (K5) ---------- */
const CHASE_PATH=[[40,436],[680,436],[680,756],[360,756],[360,885]];
function startChase(){ A_.chase={s:0,speed:72,box:{x:CHASE_PATH[0][0],y:CHASE_PATH[0][1]}}; G.p.x=120; G.p.y=560; G.hazards=[]; spawnHazard('email'); spawnHazard('email'); app.classList.add('chase'); $('abilityName').innerHTML='Tu to dej<small class="desktop-only">mezerník</small>'; toast('Chyť krabici.'); }
function chasePos(s){ let acc=0; for(let i=0;i<CHASE_PATH.length-1;i++){ const [x1,y1]=CHASE_PATH[i],[x2,y2]=CHASE_PATH[i+1]; const L=Math.hypot(x2-x1,y2-y1); if(s<=acc+L){ const k=(s-acc)/L; return {x:x1+(x2-x1)*k,y:y1+(y2-y1)*k,done:false}; } acc+=L; } const e=CHASE_PATH[CHASE_PATH.length-1]; return {x:e[0],y:e[1],done:true}; }
function updateChase(dt){
  const ch=A_.chase, p=G.p; ch.s+=ch.speed*dt; const pos=chasePos(ch.s); ch.box.x=pos.x; ch.box.y=pos.y;
  if(Math.hypot(pos.x-p.x,pos.y-p.y)<48){ A_.chase=null; app.classList.remove('chase'); G.hazards=[]; burst(pos.x,pos.y,'#c9a45c',30,240); sfx.win(); give('nabijecka');
    runDlg([ ['bzucak','Mám ji! Tu to dej!'], ['bzucak','Uvnitř nabíječka. A tři ponožtičky.'], ['pipa','Jóó… to bylo o fous.'] ]); return; }
  if(pos.done){ A_.chase=null; app.classList.remove('chase'); G.hazards=[]; burst(PORTAL.x,PORTAL.y,G.accent,30,240); sfx.fail();
    runDlg([ ['pipa','Nóó! Projela!'], ['bzucak','Počkej… vypadla zpátky na pás!'], ['bzucak','Portál nebere krabice. Jen brašny.'], ['bzucak','Znovu!'], ()=>{ startChase(); return []; } ]); return; }
  for(const h of G.hazards){ if(h.spawn>0){ h.spawn-=dt; continue; } if(G.freeze>0) continue;
    h.x+=h.vx*dt; h.y+=h.vy*dt; if(h.x<20+h.r){h.x=20+h.r;h.vx=Math.abs(h.vx);} if(h.x>W-20-h.r){h.x=W-20-h.r;h.vx=-Math.abs(h.vx);} if(h.y<190+h.r){h.y=190+h.r;h.vy=Math.abs(h.vy);} if(h.y>H-20-h.r){h.y=H-20-h.r;h.vy=-Math.abs(h.vy);}
    const ob=hitObst(h.x,h.y,h.r); if(ob){ h.vx*=-1; h.vy*=-1; h.x+=h.vx*dt*2; h.y+=h.vy*dt*2; }
    if(p.invuln<=0 && Math.hypot(h.x-p.x,h.y-p.y)<h.r+20){ p.stun=0.7; p.invuln=1.2; p.hitT=0.35; G.shake=reduced?0:0.25; sfx.hit(); toast(pick(LINES.email)); h.vx*=-1; h.vy*=-1; } }
}
/* ---------- hunt (K4) ---------- */
const HUNT=[[600,230],[110,540],[600,840],[360,700]];
function startHunt(){ A_.hunt={i:0,t:0,glimpse:0,glimpsed:false}; }
function huntHint(){ const h=A_.hunt; const [x,y]=HUNT[h.i]; const d=Math.hypot(x-G.p.x,y-G.p.y); const lvl=Math.max(1,Math.min(5,Math.round(5-d/140))); return 'Ťukání: '+'▮'.repeat(lvl)+'▯'.repeat(5-lvl)+(lvl>=4?' · blízko':' · jdi za zvukem'); }
function updateHunt(dt){
  const h=A_.hunt; h.t+=dt; const [x,y]=HUNT[h.i]; const d=Math.hypot(x-G.p.x,y-G.p.y);
  if(h.t>1.4){ h.t=0; const vol=Math.max(0.15,Math.min(1.2,1.4-d/450)); if(!save.mute&&ac){ knockSnd(0,vol); knockSnd(0.22,vol); } }
  if(!h.glimpsed && h.i>=1 && G.p.x<260 && G.p.y>420 && G.p.y<640){ h.glimpsed=true; h.glimpse=1.4; setTimeout(()=>{ clue('Ve tmě byl kulatý stín. S bambulí.'); runDlg([['bzucak','O divej! Ve dveřích kancelář…'],['bzucak','Kulatý stín. S bambulí.'],['bzucak','A je pryč.']]); },700); }
  h.glimpse=Math.max(0,h.glimpse-dt);
  if(d<60){ if(h.i<HUNT.length-1){ h.i++; h.t=1.2; toast(h.i===1?'Ťukání se přesunulo.':h.i===2?'Zase jinde. Někdo utíká.':'Teď je to blízko.'); }
    else { A_.hunt=null; F().huntDone=true; advRefresh(); runDlg([['bzucak','Ticho.'],['bzucak','Ťukání přestalo. Tady.'],['bzucak','Na zemi leží můj Střední trojúhelník.'],['bzucak','Všechno ostatní mi vypadlo z rukou.']]); } }
}

/* ---------- update ---------- */
function updateAdv(dt){
  const p=G.p; G.t+=dt; A_.doorCd=Math.max(0,A_.doorCd-dt);
  G.abCd=Math.max(0,G.abCd-dt); G.freeze=Math.max(0,G.freeze-dt); G.shake=Math.max(0,G.shake-dt);
  ['invuln','stun','boost','ghost','bubble'].forEach(k=>p[k]=Math.max(0,p[k]-dt));
  const dv=isDark(); G.dark = dv ? (dv===true?3:dv) : Math.max(0,G.dark-dt*3);
  if(A_.ui){ animUpdate(p,dt,0); return; }
  let [dx,dy]=A_.dlg?[0,0]:inputVec();
  if(dx||dy){ p.goto=null; p.target=null; }
  if(!dx&&!dy&&p.goto&&!A_.dlg){ const gx=p.goto.x-p.x, gy=p.goto.y-p.y, gd=Math.hypot(gx,gy); const stopAt=p.target?p.target.reach-6:8;
    if(gd<=stopAt){ const t=p.target; p.goto=null; p.target=null; if(t) interact(t); } else { dx=gx/gd; dy=gy/gd; } }
  if(dx||dy){ p.lastDx=dx; p.lastDy=dy; if(Math.abs(dx)>0.15){ const nd=dx<0?-1:1; if(nd!==p.dir) p.turnT=0.16; p.dir=nd; } }
  let sp=245; if(inPuddle(p.x,p.y)) sp*=0.5; if(p.stun>0){ dx=0; dy=0; }
  let mvx=dx*sp, mvy=dy*sp;
  for(const b of BELTS){ if(inRect(p.x,p.y,b)) mvx+=b.dir*b.sp*(A_.chase?1:0.5); }
  const ox=p.x, oy=p.y; moveCircle(p,mvx*dt,mvy*dt,22);
  if(p.goto && (dx||dy) && Math.hypot(p.x-ox,p.y-oy)<sp*dt*0.15){ p.stuckT=(p.stuckT||0)+dt; if(p.stuckT>0.4){ p.goto=null; p.target=null; p.stuckT=0; } } else p.stuckT=0;
  p.moving=Math.hypot(p.x-ox,p.y-oy)>sp*dt*0.2;
  animUpdate(p,dt,Math.hypot(dx,dy)*sp);
  if(!A_.dlg && !A_.chase && !A_.hunt && A_.doorCd<=0){ for(const d of (DOORS[ROOMID]||[])){ if(inRect(p.x,p.y,d,4)){ goRoom(d.to); break; } } }
  if(ROOM.drips){ G.nextDrip-=dt; if(G.nextDrip<=0){ G.nextDrip=1.4+Math.random()*1.6; G.drips.push({x:80+Math.random()*(W-160),y:220+Math.random()*(H-300),t:0}); } }
  G.drips=G.drips.filter(d=>{ d.t+=dt; if(d.t>=0.95&&!d.hit){ d.hit=true; burst(d.x,d.y,'#7fb3ea',12,150); } return d.t<1.25; });
  if(A_.chase) updateChase(dt);
  if(A_.hunt && !A_.dlg) updateHunt(dt);
  G.particles=G.particles.filter(q=>{ q.t+=dt; q.x+=q.vx*dt; q.y+=q.vy*dt; q.vx*=0.92; q.vy*=0.92; return q.t<q.life; });
  G.floats=G.floats.filter(f=>{ f.t+=dt; return f.t<1.2; });
  advHUD(false);
  $('abilityCd').style.transform=`scaleX(${G.abCd/G.c.ab.cd})`;
  if(Math.floor(G.t)%5===0 && Math.floor(G.t-dt)%5!==0) storyPersist();
}

/* ---------- chapter end ---------- */
