function buildAdv3D(room,g){
  const T3=THREE; room.adv={props:[]};
  for(const h of advHots()){ if(!h.prop) continue; const m=propMesh(h.prop,h.h); m.position.set(h.x,0,h.y); g.add(m); room.adv.props.push({h,m}); }
  // decor
  const lampM=lambert(0x2a2a30), bulbM=new T3.MeshBasicMaterial({color:0xfff2c8});
  const lamps={dilna:[[164,370],[556,370],[164,660],[556,660]],kancelar:[[360,300],[200,480],[520,480]],sklad:[[110,300],[610,300],[360,520]],expedice:[[164,300],[556,300],[360,640]],puda:[[360,560]]}[ROOMID]||[];
  for(const [x,z] of lamps){ const cord=new T3.Mesh(new T3.CylinderGeometry(0.8,0.8,60,4),lampM); cord.position.set(x,230,z); g.add(cord); const sh=new T3.Mesh(new T3.ConeGeometry(18,16,16,1,true),lambert(0x3a3a42,{side:T3.DoubleSide})); sh.position.set(x,196,z); g.add(sh); const bl=new T3.Mesh(new T3.SphereGeometry(5,10,8),bulbM); bl.position.set(x,190,z); g.add(bl); room.lights.push({m:bl,kind:'lamp'}); }
  if(ROOMID==='dilna'){ const cab=new T3.Mesh(new T3.TorusGeometry(40,2,6,24,Math.PI),lambert(0x101012)); cab.rotation.x=Math.PI/2; cab.position.set(470,2,560); g.add(cab); }
  if(ROOMID==='expedice'){ const t=texCanvas(320,90,(x,w,h)=>{ x.fillStyle='#101012'; x.fillRect(0,0,w,h); x.strokeStyle='#eeee3a'; x.lineWidth=6; x.strokeRect(4,4,w-8,h-8); x.fillStyle='#eeee3a'; x.font='800 30px "Bricolage Grotesque", sans-serif'; x.textAlign='center'; x.fillText('PORTÁL · JEN BRAŠNY',w/2,58); }); const m=new T3.Mesh(new T3.PlaneGeometry(150,42),new T3.MeshBasicMaterial({map:t})); m.position.set(560,150,-4); g.add(m);
    const bx=new T3.Group(); const b1=new T3.Mesh(new T3.BoxGeometry(44,34,40),lambert(0xb08c4f)); b1.position.y=27; b1.castShadow=true; bx.add(b1); const tape=new T3.Mesh(new T3.BoxGeometry(10,34.6,40.6),lambert(0xe2c27e)); tape.position.y=27; bx.add(tape); bx.visible=false; g.add(bx); room.adv.box=bx; }
  if(ROOMID==='sklad'){ for(let i=0;i<5;i++){ const r=new T3.Mesh(new T3.CylinderGeometry(14,14,40,14),lambert(COLORS[(i*2)%7])); r.position.set(600+(i%2)*20,20,850-i*30); r.castShadow=true; g.add(r);} }
  if(ROOMID==='kancelar'){ const rack=lambert(0x3a3a42); const st=new T3.Mesh(new T3.CylinderGeometry(3,3,140,8),rack); st.position.set(70,70,860); g.add(st); const hat=new T3.Mesh(new T3.SphereGeometry(14,12,10,0,Math.PI*2,0,Math.PI/2),lambert(0x2f86e0)); hat.position.set(70,140,860); g.add(hat); const pom=new T3.Mesh(new T3.SphereGeometry(6,8,6),lambert(0xedece8)); pom.position.set(70,156,860); g.add(pom); }
  // doors
  for(const d of (DOORS[ROOMID]||[])){ const left=d.x<W/2; const x=left?-6:W-14; const cy=d.y+d.h/2; const fr=lambert(0x3a3a42); box(g,x,cy-46,20,8,130,fr); box(g,x,cy+38,20,8,130,fr); box(g,x,cy-46,20,92,10,fr,130); const dark=new T3.Mesh(new T3.PlaneGeometry(84,130),new T3.MeshBasicMaterial({color:0x050506})); dark.rotation.y=left?Math.PI/2:-Math.PI/2; dark.position.set(left?14.5:W-14.5,65,cy); g.add(dark); const mat=new T3.Mesh(new T3.PlaneGeometry(60,d.h),new T3.MeshBasicMaterial({color:new T3.Color(G.accent),transparent:true,opacity:0.18,depthWrite:false})); mat.rotation.x=-Math.PI/2; mat.position.set(left?44:W-44,1.3,cy); g.add(mat); }
}
function advRender3D(T){
  const ra=R3.room.adv||{};
  if(ra.box){ ra.box.visible=!!A_.chase; if(A_.chase){ ra.box.position.set(A_.chase.box.x,0,A_.chase.box.y); ra.box.rotation.y=Math.sin(T*3)*0.1; } }
  for(const l of R3.room.lights){ if(l.kind==='lamp') l.m.material.color.setRGB(1,0.95,0.78).multiplyScalar(G.dark>0?0.08:0.9); }
}
function advDraw2D(T){
  for(const h of advHots()){ if(!h.prop) continue; const x=h.x,y=h.y; ctx.save();
    switch(h.prop){
     case 'ladder': ctx.strokeStyle='#7a6238'; ctx.lineWidth=5; ctx.beginPath(); ctx.moveTo(x-14,y+25); ctx.lineTo(x-14,y-45); ctx.moveTo(x+14,y+25); ctx.lineTo(x+14,y-45); ctx.stroke(); ctx.lineWidth=3; for(let yy=y-37;yy<y+25;yy+=14){ ctx.beginPath(); ctx.moveTo(x-14,yy); ctx.lineTo(x+14,yy); ctx.stroke(); } break;
     case 'clock': ctx.fillStyle='#edece8'; ctx.beginPath(); ctx.arc(x,y-30,20,0,Math.PI*2); ctx.fill(); ctx.strokeStyle='#101012'; ctx.lineWidth=3; ctx.beginPath(); ctx.moveTo(x,y-30); ctx.lineTo(x,y-46); ctx.moveTo(x,y-30); ctx.lineTo(x+12,y-30); ctx.stroke(); break;
     case 'switch': ctx.fillStyle='#edece8'; rr(x-8,y-14,16,26,3); ctx.fill(); ctx.fillStyle='#ee6a55'; ctx.fillRect(x-3,y-6,6,8); break;
     case 'coffee': ctx.fillStyle='#2b2b31'; rr(x-14,y-20,28,26,5); ctx.fill(); ctx.fillStyle='#ee6a55'; ctx.beginPath(); ctx.arc(x,y,3,0,Math.PI*2); ctx.fill(); break;
     case 'broom': ctx.strokeStyle='#c9a45c'; ctx.lineWidth=4; ctx.beginPath(); ctx.moveTo(x-40,y); ctx.lineTo(x+30,y); ctx.stroke(); ctx.fillStyle='#e2c27e'; ctx.fillRect(x+30,y-12,14,24); break;
     case 'box': case 'box_seal': ctx.fillStyle='#b08c4f'; rr(x-24,y-20,48,40,5); ctx.fill(); ctx.fillStyle=h.prop==='box_seal'?'#2f86e0':'#e2c27e'; ctx.fillRect(x-5,y-20,10,40); break;
     case 'wetpaper': ctx.fillStyle='rgba(154,176,196,0.8)'; ctx.fillRect(x-13,y-17,26,34); break;
     case 'cable': ctx.strokeStyle='#edece8'; ctx.lineWidth=4; ctx.beginPath(); ctx.arc(x,y,14,0,Math.PI*2); ctx.stroke(); break;
     case 'cabinet': ctx.fillStyle='#34343b'; rr(x-30,y-40,60,60,6); ctx.fill(); ctx.fillStyle='#c9a45c'; ctx.fillRect(x+10,y-14,8,10); break;
     case 'hatch': ctx.fillStyle='#050506'; ctx.fillRect(x-35,y-25,70,70); ctx.strokeStyle='#7a6238'; ctx.lineWidth=4; ctx.strokeRect(x-35,y-25,70,70); break;
     case 'bucket': ctx.fillStyle='#7a8a99'; rr(x-14,y-14,28,24,4); ctx.fill(); break;
     case 'chair': ctx.fillStyle='#5a3a2a'; rr(x-30,y-30,60,50,8); ctx.fill(); break;
     case 'pallets': ctx.fillStyle='#8a6f45'; ctx.fillRect(x-45,y-30,90,60); ctx.fillStyle='#b08c4f'; ctx.fillRect(x-36,y-24,30,24); ctx.fillRect(x+6,y-24,30,24); break;
     default: if(h.prop.startsWith('bag_')){ const id=h.prop.split('_')[1]; drawSprite('b_'+id,x,y+(h.prop==='bag_pipa_high'?-20:10),h.prop==='bag_tecka_desk'?40:50,false,1); }
    } ctx.restore(); }
  if(ROOMID==='expedice' && A_.chase){ const b=A_.chase.box; ctx.fillStyle='#b08c4f'; rr(b.x-22,b.y-20,44,40,5); ctx.fill(); ctx.fillStyle='#e2c27e'; ctx.fillRect(b.x-5,b.y-20,10,40); }
  for(const d of (DOORS[ROOMID]||[])){ ctx.fillStyle='rgba(237,236,232,0.08)'; ctx.fillRect(d.x<W/2?14:W-74,d.y,60,d.h); ctx.fillStyle='#050506'; ctx.fillRect(d.x<W/2?6:W-22,d.y+6,16,d.h-12); }
}
